129	            }
130	        }
131	        int above = 0;
132	        for (Long p = pool.getId(); p != null; p = parent.get(p)) {
133	            if (p.equals(member.getId())) {
134	                throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                        member.getName() + " would contain itself through " + pool.getName() + ".");
136	            }
137	            above++;
138	        }
139	        if (parent.containsKey(member.getId())) {
140	            throw new ResponseStatusException(HttpStatus.CONFLICT, member.getName() + " is already a member of a pool.");
141	        }
142	        if (above + height(member.getId(), parent) > MAX_DEPTH) {
143	            throw new ResponseStatusException(HttpStatus.CONFLICT,
144	                    "A chain of pools may be at most " + MAX_DEPTH + " deep.");
145	        }
146	        PoolMember membership = PoolMember.ofPool(sheetId, pool.getId(), member.getId(), scaled);
147	        membership.setDates(from, to);
148	        PoolMember added = members.saveAndFlush(membership);
149	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + by + " pool=" + pool.getName()
150	                + " name=" + member.getName() + " share=" + scaled.toPlainString() + dated(from, to));
151	        return added;
152	    }
153	
154	    /** How many pools deep the chain below a pool goes, the pool itself counted. */
155	    private static int height(Long poolId, Map<Long, Long> parent) {
156	        int most = 0;
