12	import java.util.LinkedHashMap;
13	import java.util.List;
14	import java.util.Map;
15	import java.util.Set;
16	import java.util.concurrent.atomic.AtomicLong;
17	import java.util.function.Supplier;
18	import java.util.stream.Collectors;
19	import java.util.stream.IntStream;
20	import javax.sql.DataSource;
21	import net.officefloor.hq.app.rate.RateChain;
22	import org.springframework.data.domain.Limit;
23	import org.springframework.jdbc.core.JdbcTemplate;
24	import org.springframework.jdbc.datasource.DriverManagerDataSource;
25	import org.springframework.stereotype.Service;
26	import org.springframework.transaction.PlatformTransactionManager;
