28	import org.springframework.transaction.annotation.Isolation;
29	import org.springframework.transaction.annotation.Transactional;
30	import org.springframework.transaction.support.TransactionTemplate;
31	
32	/**
33	 * Keeps every state each sheet stands in, and answers for a sheet as it stood at the end of a day.
34	 *
35	 * After each change to a sheet, every row kept for it is stored, with the sheet's today then (see
36	 * {@link #capture}). The rows kept for a sheet are found from the schema itself: those of the sheet, of each table
37	 * with a sheet_id, and of each table that refers to rows so kept; so a table added later is kept with no more ado.
38	 *
39	 * A sheet as of a day is a store of its own (see {@link #storeAsOf}): the schema, holding the last state stored
40	 * while the sheet's today was on or before the day (an empty sheet when there is none), with the day as its today;
41	 * and the same for each of its parent sheets whose rates it can take, each as it stood at the end of the day by its own
42	 * today (as a statement as of the day takes their rates), linked as they are now.
43	 * The whole app reads it unchanged, so every figure on the screen is as of the day.
44	 */
45	@Service
46	public class AsOfService {
47	
48	    /** The tables that keep no sheet's data. */
49	    private static final Set<String> NOT_KEPT = Set.of("FLYWAY_SCHEMA_HISTORY", "SHEET_SNAPSHOT");
50	
51	    /** How many stores as of a day are kept at once, each for a sheet's state and a day. */
52	    private static final int STORES_KEPT = 32;
53	
54	    /** A table whose rows are kept for a sheet: the stored columns, and the rows' filter by the sheet's id. */
55	    private record Kept(String table, List<String> columns, String where) {
56	    }
57	
58	    /** A store as of a day, kept alive by its open connection. */
59	    private record Store(DataSource dataSource, Connection holder) {
60	    }
61	
62	    private final DataSource dataSource;
63	    private final JdbcTemplate jdbc;
64	    private final SheetSnapshotRepository snapshots;
65	    private final TransactionTemplate readOnly;
66	    private final AtomicLong storeNames = new AtomicLong();
67	    private final Map<String, Store> stores = new LinkedHashMap<>(16, 0.75f, true);
68	    private volatile List<Kept> kept;
69	    private volatile List<String> schema;
70	
71	    public AsOfService(DataSource dataSource, SheetSnapshotRepository snapshots,
72	            PlatformTransactionManager transactions) {
73	        this.dataSource = dataSource;
74	        this.jdbc = new JdbcTemplate(dataSource);
75	        this.snapshots = snapshots;
76	        this.readOnly = new TransactionTemplate(transactions);
77	        this.readOnly.setReadOnly(true);
78	        this.readOnly.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
79	    }
80	
81	    /**
82	     * Reads the sheet as it stood at the end of the day (see {@link #storeAsOf}): the read runs in a transaction of its
83	     * own on that store, so it sees nothing read from the store itself or from another sheet as of a day. To be called
84	     * while the request in hand reads the store itself.
85	     */
86	    public <T> T readAsOf(String sheetId, LocalDate day, Supplier<T> read) {
87	        if (AsOfContext.active()) {
88	            throw new IllegalStateException("Already reading a sheet as of a date");
89	        }
90	        AsOfContext.enter(storeAsOf(sheetId, day));
91	        try {
92	            return readOnly.execute(status -> read.get());
93	        } finally {
94	            AsOfContext.leave();
95	        }
96	    }
97	
98	    /** Stores the sheet's state as it stands now, with its today, unless it is the state last stored. */
99	    @Transactional(isolation = Isolation.REPEATABLE_READ)
100	    public void capture(String sheetId) {
101	        List<LocalDate> today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId);
102	        if (today.isEmpty()) {
103	            return;
104	        }
105	        List<SheetState.Table> tables = new ArrayList<>();
106	        for (Kept k : kept()) {
107	            String columns = k.columns().stream().map(AsOfService::quoted).collect(Collectors.joining(", "));
108	            String order = IntStream.rangeClosed(1, k.columns().size()).mapToObj(Integer::toString)
109	                    .collect(Collectors.joining(", "));
110	            List<Object[]> rows = jdbc.query(
111	                    "SELECT " + columns + " FROM " + quoted(k.table()) + " WHERE " + k.where() + " ORDER BY " + order,
112	                    (rs, n) -> {
113	                        Object[] row = new Object[k.columns().size()];
114	                        for (int i = 0; i < row.length; i++) {
115	                            row[i] = rs.getObject(i + 1);
116	                        }
117	                        return row;
118	                    }, sheetId);
119	            tables.add(new SheetState.Table(k.table(), k.columns(), rows));
120	        }
121	        byte[] data = new SheetState(tables).toBytes();
122	        String digest = SheetState.digest(data);
123	        if (snapshots.latestDigests(sheetId, Limit.of(1)).contains(digest)) {
124	            return;
125	        }
126	        snapshots.saveAndFlush(new SheetSnapshot(sheetId, today.get(0), digest, data));
127	    }
128	
129	    /**
130	     * The store holding the sheet as it stood at the end of the day: the last state stored while its today was on or
131	     * before the day (an empty sheet with none), with the day standing in for its today; each parent sheet as it was
132	     * last stored while its own today was on or before the day, else as it was when the sheet's own state was stored
133	     * (an empty sheet with neither). Only to be read.
134	     */
135	    @Transactional(readOnly = true)
136	    public DataSource storeAsOf(String sheetId, LocalDate day) {
137	        Map<String, String> lineage = lineage(sheetId);
138	        List<Long> ids = new ArrayList<>();
139	        for (String id : lineage.keySet()) {
140	            // a parent keeps its own today: it stands as last stored while that was on or before the day; with none
141	            // so stored, it stands as it was when the sheet's own state was stored
142	            List<Long> made = snapshots.idsMadeBy(id, day, Limit.of(1));
143	            if (made.isEmpty() && !ids.isEmpty() && ids.get(0) != null) {
144	                made = snapshots.idsStoredBy(id, ids.get(0), Limit.of(1));
145	            }
146	            ids.add(made.isEmpty() ? null : made.get(0));
147	        }
148	        String key = lineage + "|" + ids + "|" + day;
149	        synchronized (stores) {
150	            Store store = stores.get(key);
151	            if (store == null) {
152	                List<SheetState> states = new ArrayList<>();
153	                for (Long id : ids) {
154	                    states.add(id == null ? null : SheetState.of(snapshots.findById(id).orElseThrow().getData()));
155	                }
156	                store = open(lineage, day, states);
157	                stores.put(key, store);
158	                if (stores.size() > STORES_KEPT) {
159	                    String eldest = stores.keySet().iterator().next();
160	                    close(stores.remove(eldest));
161	                }
162	            }
163	            return store.dataSource();
164	        }
165	    }
166	
167	    /**
168	     * The sheet's id, then its parent's, and so on as far as its rates can be taken from (see {@link RateChain}), each
169	     * with its parent's id as it is now (null for none).
170	     */
171	    private Map<String, String> lineage(String sheetId) {
172	        Map<String, String> lineage = new LinkedHashMap<>();
173	        String at = sheetId;
174	        while (at != null && !lineage.containsKey(at) && lineage.size() <= RateChain.LEVELS_UP) {
175	            List<String> parent = jdbc.queryForList("SELECT parent_id FROM sheet WHERE id = ?", String.class, at);
176	            String next = parent.isEmpty() ? null : parent.get(0);
177	            lineage.put(at, next);
178	            at = next;
179	        }
180	        return lineage;
181	    }
182	
183	    /**
184	     * Opens a store of its own with the schema and, for each sheet of the lineage, its state's rows (an empty sheet
185	     * with none) and its parent as it is now; the day stands in for the first one's today.
186	     */
187	    private Store open(Map<String, String> lineage, LocalDate day, List<SheetState> states) {
188	        String sheetId = lineage.keySet().iterator().next();
189	        String url = "jdbc:h2:mem:asof-" + storeNames.incrementAndGet();
190	        try {
191	            Connection holder = DriverManager.getConnection(url, "sa", "");
192	            try (Statement st = holder.createStatement()) {
193	                for (String sql : schema()) {
194	                    st.execute(sql);
195	                }
196	                // the store closes once its last connection does
197	                st.execute("SET DB_CLOSE_DELAY 0");
198	                // the rows are as they stood together, in whatever order; they are read, never changed
199	                st.execute("SET REFERENTIAL_INTEGRITY FALSE");
200	            }
201	            for (SheetState state : states) {
202	                if (state == null) {
203	                    continue;
204	                }
205	                for (SheetState.Table t : state.tables()) {
206	                    if (t.rows().isEmpty()) {
207	                        continue;
208	                    }
209	                    String sql = "INSERT INTO " + quoted(t.name()) + " ("
210	                            + t.columns().stream().map(AsOfService::quoted).collect(Collectors.joining(", "))
211	                            + ") VALUES (" + t.columns().stream().map(c -> "?").collect(Collectors.joining(", ")) + ")";
212	                    try (PreparedStatement insert = holder.prepareStatement(sql)) {
213	                        for (Object[] row : t.rows()) {
214	                            for (int i = 0; i < row.length; i++) {
215	                                insert.setObject(i + 1, row[i]);
216	                            }
217	                            insert.addBatch();
218	                        }
219	                        insert.executeBatch();
220	                    }
221	                }
222	            }
223	            try (PreparedStatement today = holder.prepareStatement("UPDATE sheet SET today = ? WHERE id = ?")) {
224	                today.setObject(1, day);
225	                today.setString(2, sheetId);
226	                today.executeUpdate();
227	            }
228	            for (Map.Entry<String, String> link : lineage.entrySet()) {
229	                try (PreparedStatement parent = holder.prepareStatement(
230	                        "UPDATE sheet SET parent_id = ? WHERE id = ?")) {
231	                    parent.setString(1, link.getValue());
232	                    parent.setString(2, link.getKey());
233	                    if (parent.executeUpdate() == 0) {
234	                        try (PreparedStatement empty = holder.prepareStatement("INSERT INTO sheet"
235	                                + " (id, created_at, today, parent_id) VALUES (?, CURRENT_TIMESTAMP, ?, ?)")) {
236	                            empty.setString(1, link.getKey());
237	                            empty.setObject(2, day);
238	                            empty.setString(3, link.getValue());
239	                            empty.executeUpdate();
240	                        }
241	                    }
242	                }
243	            }
244	            return new Store(new DriverManagerDataSource(url + ";IFEXISTS=TRUE", "sa", ""), holder);
245	        } catch (SQLException e) {
246	            throw new IllegalStateException("Could not open the sheet as of " + day, e);
247	        }
248	    }
249	
250	    private static void close(Store store) {
251	        try {
252	            store.holder().close();
253	        } catch (SQLException e) {
254	            // already gone
255	        }
256	    }
257	
258	    /** The schema, as statements that create it empty. */
259	    private List<String> schema() {
260	        List<String> s = schema;
261	        if (s == null) {
262	            s = List.copyOf(jdbc.queryForList("SCRIPT NODATA", String.class));
263	            schema = s;
264	        }
265	        return s;
266	    }
267	
268	    /** The tables whose rows are kept for a sheet, found from the schema. */
269	    private List<Kept> kept() {
270	        List<Kept> k = kept;
271	        if (k == null) {
272	            k = jdbc.execute(AsOfService::findKept);
273	            kept = k;
274	        }
275	        return k;
276	    }
277	
278	    private static List<Kept> findKept(Connection c) throws SQLException {
279	        Map<String, List<String>> columns = new LinkedHashMap<>();
280	        Map<String, Boolean> hasSheetId = new LinkedHashMap<>();
281	        try (PreparedStatement q = c.prepareStatement(
