26	// while the pool is unbalanced or has no pot, or while the member's dates do not include the sheet's today.
27	export interface ShownMember extends PoolMemberView {
28	  key: string;
29	  // Whether the membership's dates leave out the sheet's today.
30	  out: boolean;
31	  cut: string;
32	}
