34	export interface PoolView {
35	  id: number;
36	  name: string;
37	  members: PoolMemberView[];
38	  totalShare: string;
39	  balanced: boolean;
40	  // Set on a crew's pool: the crew it stands for (its members are the crew's, and none are added here).
41	  crewId?: number;
42	}
