44	/**
45	 * A crew as a pool, under the crew's name (keyed by the negated crew id, apart from the stored pools): its lead and
46	 * members, in that order, at equal shares of 100.00 split as patrons' shares are, the remainder on the lead.
47	 */
48	function crewPool(crew: CrewView, names: ReadonlyMap<number, string>): PoolView {
49	  const people = [
50	    ...(crew.leadId === null ? [] : [{ personId: crew.leadId, name: crew.leadName }]),
51	    ...crew.members.map((m) => ({ personId: m.personId, name: m.name })),
52	  ];
53	  const shares = equalShares(people.length);
54	  return {
55	    id: -crew.id,
56	    name: crew.name,
57	    members: people.map((p, i) => ({
58	      personId: p.personId,
59	      poolId: null,
60	      name: names.get(p.personId) ?? p.name,
61	      share: shares[i],
62	      retired: false,
63	      from: null,
64	      to: null,
65	    })),
66	    totalShare: '100.00',
67	    balanced: true,
68	    crewId: crew.id,
69	  };
70	}
