72	// A person as the pools see them: who may be chosen as a member, whether they are retired, and their holds (each
73	// from its from-date to its to-date, null: with no end, both included).
74	export interface RosterPerson {
75	  id: number;
76	  name: string;
77	  retiredFrom: string | null;
78	  holds: readonly { from: string; to: string | null }[];
79	}
