81	// The people of the active sheet as the people list holds them now, so a pool offers each and counts a member retired
82	// as soon as they are.
83	@Injectable({ providedIn: 'root' })
84	export class PoolRoster {
85	  readonly people = signal<readonly RosterPerson[]>([]);
86	}
87	
88	const SHARE = /^\d{1,3}(\.\d{1,2})?$/;
89	const DATE = /^\d{4}-\d{2}-\d{2}$/;
90	
91	// Whether a membership's dates include the day (with no day known, every membership counts).
92	function dated(m: { from: string | null; to: string | null }, day: string | null): boolean {
93	  return day === null || ((m.from === null || m.from <= day) && (m.to === null || day <= m.to));
94	}
95	
96	// The most pools in a chain, the top one counted.
97	const MAX_DEPTH = 3;
98	
99	// Each pool that is a member of another, to the pool it is in.
100	function parents(pools: readonly PoolView[]): Map<number, number> {
101	  const parent = new Map<number, number>();
102	  for (const p of pools) for (const m of p.members) if (m.poolId !== null) parent.set(m.poolId, p.id);
103	  return parent;
104	}
105	
106	// How many pools deep the chain below a pool goes, the pool itself counted.
107	function height(pool: number, parent: ReadonlyMap<number, number>): number {
108	  let most = 0;
109	  for (const [child, of] of parent) if (of === pool) most = Math.max(most, height(child, parent));
110	  return most + 1;
111	}
112	
113	// The share percents as a whole number of hundredths.
114	function hundredths(share: string): number {
115	  const [whole, frac = ''] = share.split('.');
116	  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
117	}
118	
119	function percent(h: number): string {
120	  return `${Math.floor(h / 100)}.${String(h % 100).padStart(2, '0')}`;
121	}
122	
123	// An amount of two decimals as a whole number of cents, and back.
124	function cents(amount: string): bigint {
125	  const [whole, frac = ''] = amount.split('.');
126	  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
127	}
128	
129	function money(c: bigint): string {
130	  return `${c / 100n}.${String(c % 100n).padStart(2, '0')}`;
131	}
132	
133	/**
134	 * Each member's cut of the pot (in cents), in member order: the pot times their share over the shares of the members
135	 * with a cut added up, rounded half to even to the cent; a retired member, one held on the sheet's today, and one
136	 * whose dates do not include it, has none (0). The remainder left by the rounding goes to the member with the smallest
137	 * non-zero cut (the latest added on a tie), or, with no non-zero cut, to the last member with a share, so the cuts
138	 * total exactly the pot; with no member left with a cut, each is 0, except that a pool whose every member is retired has no cuts at all (null).
139	 */
140	function cuts(
141	  pot: bigint,
142	  members: readonly { share: string; retired: boolean; held: boolean; out: boolean }[],
143	): bigint[] | null {
144	  if (members.length > 0 && members.every((m) => m.retired)) return null;
145	  const shares = members.map((m) => (m.retired || m.held || m.out ? 0n : BigInt(hundredths(m.share))));
146	  const of = shares.reduce((sum, h) => sum + h, 0n);
147	  if (of === 0n) return shares.map(() => 0n);
148	  const result = shares.map((h) => {
149	    const exact = pot * h;
150	    let q = exact / of;
151	    const r = (exact % of) * 2n;
152	    if (r > of || (r === of && q % 2n === 1n)) q += 1n;
153	    return q;
154	  });
155	  let to = -1;
156	  result.forEach((c, i) => {
157	    if (c !== 0n && (to < 0 || c <= result[to])) to = i;
158	  });
159	  if (to < 0) {
160	    shares.forEach((h, i) => {
161	      if (h > 0n) to = i;
162	    });
163	  }
164	  result[to] += pot - result.reduce((sum, c) => sum + c, 0n);
165	  return result;
166	}
