168	// The active sheet's pools as last read from the store, and what they work out to: each member's cut, and each
169	// person's cut total.
170	@Injectable({ providedIn: 'root' })
171	export class PoolStore {
172	  private readonly roster = inject(PoolRoster);
173	  private readonly settings = inject(SettingsStore);
174	  private readonly session = inject(Session);
175	  private readonly crews = inject(CrewRoster);
176	
177	  readonly pools = signal<readonly PoolView[]>([]);
178	  // The stored pools, then each crew as a pool, in the order the crews were added.
179	  readonly all = computed(() => {
180	    const names = new Map(this.roster.people().map((p) => [p.id, p.name]));
181	    return [...this.pools(), ...this.crews.crews().map((c) => crewPool(c, names))];
182	  });
183	  // Every name a pool or a crew goes by: a pool cannot take a crew's name, nor a crew a pool's.
184	  readonly names = computed(() => new Set(this.all().map((p) => p.name)));
185	  // The pools with each member counted retired as the people list has them now, the totals to match, and each
186	  // member's cut of the pool's pot while the pool is balanced: the sheet's pot for a pool that is a member of none,
187	  // else its cut in the pool above. A member retired, or held on the sheet's today, counts toward the total but has no
188	  // cut; a member whose dates do not include the sheet's today is left out entirely.
189	  readonly shown = computed(() => {
190	    const retired = new Map(this.roster.people().map((p) => [p.id, p.retiredFrom !== null]));
191	    const today = this.session.sheetToday();
192	    const held = new Set(
193	      this.roster
194	        .people()
195	        .filter((p) => today !== null && p.holds.some((h) => h.from <= today && (h.to === null || today <= h.to)))
196	        .map((p) => p.id),
197	    );
198	    const pools = this.all();
199	    const parent = parents(pools);
200	    const counted = new Map(
201	      pools.map((pool) => {
202	        const members = pool.members.map((m) => ({
203	          ...m,
204	          key: m.personId !== null ? String(m.personId) : `pool-${m.name}`,
205	          retired: m.personId !== null ? (retired.get(m.personId) ?? m.retired) : false,
206	          out: !dated(m, today),
207	          held: m.personId !== null && held.has(m.personId),
208	        }));
209	        const total = members.reduce((sum, m) => sum + (m.out ? 0 : hundredths(m.share)), 0);
210	        return [pool.id, { pool, members, total, balanced: total === 10000 }] as const;
211	      }),
212	    );
213	    const sheetPot = this.settings.pot();
214	    // Each pool's cuts (in cents, in member order), or null for none; worked out top down.
215	    const cutsOf = new Map<number, bigint[] | null>();
216	    const poolCuts = (id: number): bigint[] | null => {
217	      if (cutsOf.has(id)) return cutsOf.get(id)!;
218	      const c = counted.get(id)!;
219	      let pot: bigint | null = null;
220	      const above = parent.get(id);
221	      if (above === undefined) {
222	        pot = sheetPot !== null ? cents(sheetPot) : null;
223	      } else {
224	        const i = counted.get(above)!.members.findIndex((m) => m.poolId === id);
225	        pot = poolCuts(above)?.[i] ?? null;
226	      }
227	      const result = c.balanced && pot !== null ? cuts(pot, c.members) : null;
228	      cutsOf.set(id, result);
229	      return result;
230	    };
231	    return pools.map((pool) => {
232	      const c = counted.get(pool.id)!;
233	      const cut = poolCuts(pool.id);
234	      const shownMembers: ShownMember[] = c.members.map((m, i) => ({ ...m, cut: cut && !m.out ? money(cut[i]) : '' }));
235	      return { ...pool, members: shownMembers, totalShare: percent(c.total), balanced: c.balanced };
236	    });
237	  });
238	
239	  // Each person's cut total (their cuts across every pool they are a member of, a pool showing no cuts adding
240	  // nothing), by person id; a person in no pool with a cut is absent.
241	  readonly cutTotals = computed(() => {
242	    const totals = new Map<number, string>();
243	    const sums = new Map<number, bigint>();
244	    for (const pool of this.shown())
245	      for (const m of pool.members)
246	        if (m.personId !== null && m.cut !== '') sums.set(m.personId, (sums.get(m.personId) ?? 0n) + cents(m.cut));
247	    for (const [id, c] of sums) totals.set(id, money(c));
248	    return totals;
249	  });
250	
251	  // The sheet's cut total: everyone's cut totals added up.
252	  readonly cutTotal = computed(() => {
253	    let sum = 0n;
254	    for (const t of this.cutTotals().values()) sum += cents(t);
255	    return money(sum);
256	  });
257	}
