368	export class Pools {
369	  private readonly http = inject(HttpClient);
370	  private readonly session = inject(Session);
371	  private readonly document = inject(DOCUMENT);
372	  protected readonly roster = inject(PoolRoster);
373	
374	  private readonly store = inject(PoolStore);
375	  protected readonly pools = this.store.pools;
376	  protected readonly shown = this.store.shown;
377	
378	  protected readonly name = signal('');
379	  protected readonly error = signal<string | null>(null);
380	  protected readonly choices = signal<Record<number, string>>({});
381	  protected readonly shares = signal<Record<number, string>>({});
382	  protected readonly froms = signal<Record<number, string>>({});
383	  protected readonly tos = signal<Record<number, string>>({});
384	  protected readonly rowErrors = signal<Record<number, string>>({});
385	  // A submit in flight: a second one before it answers is ignored.
386	  private submitting = false;
387	
388	  constructor() {
389	    // Re-read the pools from the store each time a sheet is loaded.
390	    effect(() => {
391	      const id = this.session.sheetId();
392	      this.session.loads();
393	      untracked(() => {
394	        this.error.set(null);
395	        this.pools.set([]);
396	        this.choices.set({});
397	        this.shares.set({});
398	        this.froms.set({});
399	        this.tos.set({});
400	        this.rowErrors.set({});
401	        if (id) this.load(id).catch(() => this.error.set('Could not load the pools.'));
402	      });
403	    });
