417	   * a pool member as pool:<name>, the cut as shown (empty when none).
418	   */
419	  protected async exportPools(): Promise<void> {
420	    await this.session.settled();
421	    const lines = [['pool', 'member', 'share', 'cut']];
422	    for (const p of this.shown())
423	      for (const m of p.members) lines.push([p.name, m.poolId !== null ? `pool:${m.name}` : m.name, m.share, m.cut]);
424	    const csv = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
425	    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
426	    const link = this.document.createElement('a');
427	    link.href = url;
428	    link.download = 'pools.csv';
429	    link.click();
