466	  }
467	
468	  // Why the pool may not take the other pool as a member, or null when it may.
469	  private poolRefusal(pool: number, member: number): string | null {
470	    const parent = parents(this.pools());
471	    let above = 0;
472	    for (let p: number | undefined = pool; p !== undefined; p = parent.get(p)) {
473	      if (p === member) return 'A pool cannot contain itself.';
474	      above++;
475	    }
476	    if (parent.has(member)) return 'That pool is already a member of a pool.';
477	    if (above + height(member, parent) > MAX_DEPTH) return `A chain of pools may be at most ${MAX_DEPTH} deep.`;
478	    return null;
479	  }
480	
481	  protected async add(e: Event): Promise<void> {
482	    e.preventDefault();
483	    if (this.submitting) return;
484	    this.error.set(null);
485	    const sheet = this.session.sheetId();
486	    if (!sheet) return;
487	    const name = this.name().trim();
488	    if (!name) {
489	      this.error.set('Enter a pool name.');
490	      return;
491	    }
492	    if (this.store.names().has(name)) {
493	      this.error.set(`${name} is already a pool or a crew.`);
494	      return;
495	    }
496	    this.submitting = true;
497	    try {
498	      const added = await firstValueFrom(this.http.post<PoolView>(this.url(sheet), { name }));
499	      if (this.session.sheetId() === sheet) this.pools.update((l) => [...l, added]);
500	    } catch (err) {
501	      this.error.set(
502	        err instanceof HttpErrorResponse && err.status === 409 ? `${name} is already a pool or a crew.` : 'Could not add the pool.',
503	      );
504	    } finally {
505	      this.submitting = false;
506	    }
507	  }
508	
509	  protected async addMember(e: Event, pool: PoolView): Promise<void> {
510	    e.preventDefault();
511	    if (this.submitting) return;
512	    this.clearRowError(pool.id);
513	    const sheet = this.session.sheetId();
514	    if (!sheet) return;
515	    const choice = this.choices()[pool.id] ?? '';
516	    const memberPool = choice.startsWith('pool:') ? Number(choice.slice('pool:'.length)) : null;
517	    const personId = memberPool === null ? Number(choice) : null;
518	    if (!memberPool && !personId) {
519	      this.setRowError(pool.id, 'Choose a member.');
520	      return;
521	    }
522	    const share = (this.shares()[pool.id] ?? '').trim();
523	    if (!SHARE.test(share) || hundredths(share) <= 0 || hundredths(share) > 10000) {
524	      this.setRowError(pool.id, 'Enter a share of more than 0.00 and at most 100.00, with up to two decimals.');
525	      return;
526	    }
527	    const from = (this.froms()[pool.id] ?? '').trim();
