# pure function before PoolStore
fn='''export type ShownPool = Omit<PoolView, 'members'> & { members: ShownMember[] };

// The pools as of a day, for the store as it then stood: their crews' pools included, each member counted retired as
// the people then were, the totals to match, and each member's cut of the pool's pot while the pool is balanced: the
// pot for a pool that is a member of none, else its cut in the pool above. A member retired, or held on the day,
// counts toward the total but has no cut; a member whose dates do not include the day is left out entirely.
function shownPools(
  pools: readonly PoolView[],
  people: readonly RosterPerson[],
  sheetPot: string | null,
  today: string | null,
): ShownPool[] {
  const retired = new Map(people.map((p) => [p.id, p.retiredFrom !== null]));
  const held = new Set(
    people
      .filter((p) => today !== null && p.holds.some((h) => h.from <= today && (h.to === null || today <= h.to)))
      .map((p) => p.id),
  );
  const parent = parents(pools);
  const counted = new Map(
    pools.map((pool) => {
      const members = pool.members.map((m) => ({
        ...m,
        key: m.personId !== null ? String(m.personId) : `pool-${m.name}`,
        retired: m.personId !== null ? (retired.get(m.personId) ?? m.retired) : false,
        out: !dated(m, today),
        held: m.personId !== null && held.has(m.personId),
      }));
      const total = members.reduce((sum, m) => sum + (m.out ? 0 : hundredths(m.share)), 0);
      return [pool.id, { pool, members, total, balanced: total === 10000 }] as const;
    }),
  );
  // Each pool's cuts (in cents, in member order), or null for none; worked out top down.
  const cutsOf = new Map<number, bigint[] | null>();
  const poolCuts = (id: number): bigint[] | null => {
    if (cutsOf.has(id)) return cutsOf.get(id)!;
    const c = counted.get(id)!;
    let pot: bigint | null = null;
    const above = parent.get(id);
    if (above === undefined) {
      pot = sheetPot !== null ? cents(sheetPot) : null;
    } else {
      const i = counted.get(above)!.members.findIndex((m) => m.poolId === id);
      pot = poolCuts(above)?.[i] ?? null;
    }
    const result = c.balanced && pot !== null ? cuts(pot, c.members) : null;
    cutsOf.set(id, result);
    return result;
  };
  return pools.map((pool) => {
    const c = counted.get(pool.id)!;
    const cut = poolCuts(pool.id);
    const shownMembers: ShownMember[] = c.members.map((m, i) => ({ ...m, cut: cut && !m.out ? money(cut[i]) : '' }));
    return { ...pool, members: shownMembers, totalShare: percent(c.total), balanced: c.balanced };
  });
}

// The pools as they stood at the end of a period (on its to-date, the day), as the server reads them then: the
// stored pools, the crews, the people and the pot (null: none).
export interface PeriodPools {
  period: string;
  day: string;
  pools: PoolView[];
  crews: CrewView[];
  people: RosterPerson[];
  pot: string | null;
}

// The active sheet's pools as last read'''
